import json, pathlib, re
root=pathlib.Path(__file__).resolve().parents[2]
p=root/'content/grammar/v5'
def read(n): return json.loads((p/(n+'.json')).read_text())
def save(n,d): (p/(n+'.json')).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
def task(d,id): return next(q for k in ['questions','corrections','transformations','recall','items'] for q in d.get(k,[]) if q['id']==id)
d=read('day-29'); q=task(d,'gv5-d29-q15'); q.update(prompt='The editor insists ____ the source before publication. Choose the standard pattern with an -ing complement.',options=['to checking','on checking','that checking','for to check'],answer=1,why='Insist on selects a noun phrase or an -ing clause here: insists on checking the source. Insist that the source be checked is another standard pattern, but requires a finite clause.',conceptId='gv5-d25-m02',sourceIds=[]);save('day-29',d)
d=read('day-30');task(d,'gv5-d30-q04')['prompt']='In an analysis of the archive report, which quoted expression has non-finite verb structure?';d['writing']['model']=d['writing']['model'].replace('should be recorded/cannot be treated/while that work is carried out','cannot be treated/while that work is carried out');save('day-30',d)
# Recall belongs to the concept actually elicited, independently of its host day.
retag={11:['gv5-d02-m01','gv5-d05-m02','gv5-d10-m01'],15:['gv5-d04-m02','gv5-d14-m02','gv5-d12-m03'],16:['gv5-d14-m01','gv5-d15-m04','gv5-d10-m01'],21:['gv5-d20-m04','gv5-d17-m02','gv5-d15-m03'],26:['gv5-d23-m03','gv5-d17-m04','gv5-d04-m03'],27:['gv5-d21-m02','gv5-d20-m03','gv5-d26-m03']}
for n,ids in retag.items():
 d=read(f'day-{n:02}')
 for q,id in zip(d['recall'],ids): q.update(conceptId=id,sourceIds=[])
