d=read('day-01');d['writing']['model']='The library opens early. A caretaker checks the windows before the first students arrive. The reading room is quiet, and the lamps are already on. Visitors leave their bags by the entrance. During the morning, the librarian answers questions and records new loans. A small reading group meets upstairs. Its members share books and discuss their different interpretations.\n\nAnalysis: The library opens early contains subject + verb with a time adjunct. A caretaker checks the windows contains subject, verb and direct object. The reading room is quiet contains subject, linking verb and subject complement. The reading room is a whole subject; room is its head.';save('day-01',d)
d=read('day-23');d['writing']['model']=d['writing']['model'].replace('We have therefore asked the booking clerk to confirm the address before printing future labels.','We have therefore asked the booking clerk to confirm the current delivery address with the receiving office before printing future labels.');save('day-23',d)
models=[
('Describe a current study or workplace project in 90–120 words. Include a routine, a temporary activity, a completed result and an activity extending towards now. Identify the four forms after the passage.', 'Our reading group meets every Wednesday in the college library. We usually choose one short article and discuss the writer’s main argument. This week we are preparing a joint presentation instead, so each member is checking a different source. We have already agreed on the central question and collected the most relevant references. I have been comparing two accounts of the same event since Monday. Their conclusions differ, and I still need to examine the evidence behind them. The librarian helps us locate older material when a source is unavailable online. Our shared notes record uncertainties as well as useful findings.\n\nAnalysis: meets/choose describe routines; are preparing presents a temporary activity; have agreed presents a completed result; have been comparing presents an activity continuing towards now.', 'gv5-d06-m04'),
('Write a 90–120-word event update. Establish a past sequence, distinguish a future schedule from an arrangement and state what will be completed by a deadline. Identify these grammatical choices.', 'The exhibition team inspected the hall last Tuesday and found that two display boards needed repair. While the caretaker was checking the lighting, we measured the space near the entrance. We then revised the layout and sent it to the organiser. The exhibition opens at ten on Saturday, according to the published programme. I am meeting the designer on Friday to check the final signs. By Friday evening, we will have attached all the labels and tested the display screens. Visitors will be able to ask questions at a separate desk. We will report any remaining problems before the doors open.\n\nAnalysis: inspected/found/revised establish narrative sequence; was checking supplies background; opens gives a schedule; am meeting gives an arrangement; will have attached expresses completion by a future deadline.', 'gv5-d09-m02'),
('Write a 90–120-word proposal about a shared learning space. Include an identifying relative clause, an open condition, a remote alternative and a cautious modal claim. Explain the differences after the passage.', 'The room that overlooks the courtyard could become a shared study space. It is quiet during the afternoon, although it is used for classes each morning. If the department approves the proposal, we will arrange a short trial next month. Students who need a place for group discussion can book a table in advance. If we had a larger budget, we would also buy adjustable chairs, but that purchase is currently unlikely. The trial may reveal practical problems that the plan has missed. We should therefore collect comments from users before recommending a permanent change. No existing class would lose its teaching room.\n\nAnalysis: that overlooks the courtyard identifies the room. If the department approves is an open future condition. If we had a larger budget presents a remote alternative. May reveal expresses possibility, not a confirmed result.', 'gv5-d18-m01'),
('Write a 90–120-word meeting report. Include a passive, an attributed statement, an embedded question and a clear parallel list. Identify the structures after the passage.', 'The revised catalogue was discussed at Monday’s staff meeting. The curator said that several descriptions still needed checking against the original records. She asked whether the volunteers had recorded uncertain dates separately. The coordinator explained that a special column had been added for that purpose. Staff agreed to check the names, compare the dates and record unresolved questions before the next review. Only after those checks have been completed will the catalogue be prepared for public use. The team will retain the earlier version so that later editors can trace each amendment. The report records the agreed procedure without claiming that every description is already accurate.\n\nAnalysis: was discussed is a passive. Said that attributes a claim. Whether the volunteers had recorded is an embedded question with subject–auxiliary order. Check, compare and record form a parallel list.', 'gv5-d21-m04')]
for n,(prompt,model,c) in enumerate(models,1):
 d=read(f'phase-{n}');d['title']=f'Cumulative assessment: Days 1–{n*6}';q=next(q for q in d['items'] if q['kind']=='writing');q.update(prompt=prompt,model=model,conceptId=c,sourceIds=[],rubric=['Write 90–120 words of connected prose, excluding the grammatical annotation.','Include every requested construction and identify its form and meaning.','Check reference, tense, clause boundaries and meaning; this is self-review, not an external grade.']);save(f'phase-{n}',d)
# Further cumulative items are new retrieval evidence rather than copied earlier questions.
extra={2:[
('The phrase those two damaged boxes has which head?',['those','two','damaged','boxes'],3,'Boxes is the noun head. Those and two determine its reference and quantity; damaged modifies it.','gv5-d01-m04','Recognition'),
('Use advice in its ordinary uncountable sense: The adviser gave us ____.',['three advices','an advice','some useful advice','many useful advice'],2,'Some useful advice uses the ordinary uncountable sense. Three pieces of advice would count separate recommendations.','gv5-d02-m02','Application'),
('An unnamed visitor is introduced and then mentioned again: ____ visitor arrived; ____ visitor asked for a map.',['A / the','The / a','An / an','Zero article / the'],0,'A introduces an unidentified singular countable visitor; the subsequently identifies the same visitor.','gv5-d03-m01','Application'),
('The guide spoke to Lina and ____, then left.',['I','me','mine','my'],1,'The coordinated phrase is the complement of to; objective me fits this function in edited standard English.','gv5-d04-m01','Application')],3:[
('The equipment in both storerooms ____ available.',['are','have','is','be'],2,'The subject head equipment is uncountable and singular; the plural noun storerooms is inside a modifying phrase.','gv5-d02-m02','Application'),
('The visitors have submitted ____ forms. Use the ordinary possessive determiner referring to those visitors.',['theirs','there','they','their'],3,'Their determines forms and refers back to the plural visitors. Theirs is an independent possessive form.','gv5-d04-m03','Application'),
('In The curator has been checking the labels, which word is finite?',['has','been','checking','labels'],0,'Has carries present tense and third-person singular agreement. Been and checking are non-finite forms.','gv5-d05-m02','Recognition'),
('The inspection ended yesterday: The engineer ____ the roof yesterday.',['has checked','checked','checks now','had check'],1,'Past simple checked places the event in the stated completed past period.','gv5-d07-m01','Application'),
('Which sentence presents a completion deadline rather than a duration endpoint?',['Remain here until noon.','Keep waiting until noon.','Deliver the parcel by noon.','Continue working until noon.'],2,'By noon requires delivery no later than noon. Until marks the endpoint of the continuing situations in the other options.','gv5-d08-m03','Understanding'),
('The printed timetable states: The first train ____ at 06:20 tomorrow.',['departing','have departed','depart','departs'],3,'Present simple departs can express a scheduled future event and agrees with singular train.','gv5-d09-m02','Application')],4:[
('Which plural belongs to the ordinary noun criterion?',['criteria','criterionses','criterias','criteriones'],0,'Criteria is the established plural of criterion in ordinary formal usage; an extra plural ending is unnecessary.','gv5-d02-m01','Recognition'),
('Select the ordinary object form: The invitation was sent to my brother and ____.',['I','me','my','mine'],1,'To takes the whole coordinated complement my brother and me. Coordination does not require subject case.','gv5-d04-m01','Application'),
('We have been reviewing the files since dawn. Which claim follows from the verb form alone?',['Every file has been reviewed.','The review occurred only last year.','An activity is viewed over a period connected to now; completion is not guaranteed.','The activity cannot have just stopped.'],2,'Perfect progressive relates an extended activity to now; it does not guarantee completion and can describe recently stopped activity.','gv5-d08-m01','Understanding'),
('The price of the replacement parts ____ unexpectedly high.',['are','have','be','is'],3,'Singular price controls agreement. Parts is inside the modifying of-phrase.','gv5-d10-m01','Application'),
('Choose a standard embedded question after Please tell me.',['where the next meeting is','where is the next meeting','that where the next meeting is','where does the next meeting is'],0,'The embedded question has subject before finite verb: the next meeting is. Direct-question inversion is not used.','gv5-d15-m03','Application'),
('Which report preserves uncertainty in The lock may be damaged?',['The lock is certainly damaged.','The lock might be damaged.','The lock must be replaced immediately.','The lock has definitely failed.'],1,'Might can preserve a tentative possibility. The other options add certainty, a requirement or a confirmed failure.','gv5-d17-m04','Understanding')]}
for n,rows in extra.items():
 d=read(f'phase-{n}')
 for i,(prompt,opts,key,why,c,ability) in enumerate(rows,13):
  id=f'gv5-phase-{n}-q{i:02}'
  if not any(q['id']==id for q in d['items']):d['items'].insert(i-1,dict(id=id,type='objective',kind='choice',prompt=prompt,options=opts,answer=key,why=why,conceptId=c,difficulty='Intermediate',ability=ability,sourceIds=[]))
 save(f'phase-{n}',d)
# Normalise actual cognitive operations and visibly accidental missing spaces.
for f in p.glob('*.json'):
 d=json.loads(f.read_text())
 def clean(v):
  if isinstance(v,str):return re.sub(r'\b(Produce|Write|write|produce|Task|Day|Days)(?=\d)',r'\1 ',re.sub(r'(?<=\d)(?=words\b)', ' ',v))
  if isinstance(v,list):return [clean(x) for x in v]
  if isinstance(v,dict):return {k:(x if k in ['id','conceptId','sourceIds','coverageIds'] else clean(x)) for k,x in v.items()}
  return v
 d=clean(d)
 for group in ['questions','corrections','transformations','recall','items']:
  for q in d.get(group,[]):
   if q['type']=='response': q['ability']={'classification':'Recognition','function':'Understanding','analysis':'Understanding','comparison':'Understanding','gap':'Application','multiple-gap':'Application','ordering':'Application'}.get(q['kind'],'Production and revision')
 save(f.stem,d)
